insert into public.questions (subject_id, source_ref, prompt, options, correct_index, explanation, difficulty, topic, question_type, status, sort_order, banca, concurso)
values
((select id from public.subjects where slug='direito-eleitoral'), 'LAW-AUTH-107', 'A justica eleitoral e composta, em regra, por:', '["Apenas juizes de direito de primeiro grau.","Tribunais regionais eleitorais e o Tribunal Superior Eleitoral, com juizes de origem diversa.","Exclusivamente pelo Supremo Tribunal Federal.","Pelo Congresso Nacional.","Pelo Ministerio Publico."]'::jsonb, 1, 'A justica eleitoral e composta pelos tribunais regionais eleitorais e pelo Tribunal Superior Eleitoral, com composicao prevista na Constituicao.', 'medium', 'Organizacao da justica eleitoral', 'multiple_choice', 'published', 5176, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-eleitoral'), 'LAW-AUTH-108', 'A propaganda eleitoral gratuita no radio e na televisao:', '["Pode ocorrer a qualquer tempo, sem restricoes.","Ocorre no periodo previsto em lei, com regras de equidade entre os candidatos.","E vedada em qualquer hipotese.","E exclusiva do partido majoritario.","Dispensa registro de candidatura."]'::jsonb, 1, 'A propaganda eleitoral gratuita e regulada por lei e ocorre no periodo legal, com regras de equidade e tempo.', 'medium', 'Propaganda eleitoral', 'multiple_choice', 'published', 5177, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-empresarial'), 'LAW-AUTH-109', 'O empresario e a pessoa que exerce profissionalmente atividade economica organizada para a producao ou a circulacao de bens ou servicos, conforme o Codigo Civil. A empresa:', '["E o conjunto de bens do empresario, sem organizacao.","E a atividade economica organizada, exercida pelo empresario.","E apenas o estabelecimento comercial.","E a sociedade limitada, sempre.","E o registro no cartorio."]'::jsonb, 1, 'A empresa e a atividade economica organizada, distinta do empresario (sujeito) e do estabelecimento (local).', 'medium', 'Empresa e empresario', 'multiple_choice', 'published', 5178, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-empresarial'), 'LAW-AUTH-110', 'O titulo de credito, em regra, deve conter:', '["Apenas o valor da divida.","Os requisitos formais previstos em lei para sua especie, como promessa de pagamento e assinatura.","Apenas a data de vencimento.","A assinatura de duas testemunhas, sempre.","A homologacao judicial."]'::jsonb, 1, 'Cada titulo de credito tem requisitos formais proprios; a ausencia deles pode afetar sua validade ou eficacia.', 'medium', 'Titulos de credito', 'multiple_choice', 'published', 5179, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-financeiro-e-economico'), 'LAW-AUTH-111', 'O orcamento publico, em regra, compreende:', '["Apenas a lei orcamentaria anual.","O plano plurianual, as diretrizes orcamentarias e o orcamento anual.","Somente as despesas do executivo.","Apenas receitas tributarias.","Decretos do presidente."]'::jsonb, 1, 'O sistema orcamentario compreende o PPA, a LDO e a LOA, conforme a Constituicao.', 'medium', 'Orcamento publico', 'multiple_choice', 'published', 5180, 'CEBRASPE', 'Area fiscal'),
((select id from public.subjects where slug='direito-financeiro-e-economico'), 'LAW-AUTH-112', 'A ordem economica constitucional tem por fundamentos, entre outros:', '["A livre iniciativa e a valorizacao do trabalho humano.","A estatizacao de todas as atividades.","A proibicao de concorrencia.","A ausencia de regulacao.","A exclusao da intervencao do Estado."]'::jsonb, 0, 'A Constituicao funda a ordem economica na livre iniciativa e na valorizacao do trabalho humano, com principios de defesa do consumidor e reducao das desigualdades.', 'easy', 'Ordem economica', 'multiple_choice', 'published', 5181, 'FCC', 'Area fiscal'),
((select id from public.subjects where slug='direito-internacional'), 'LAW-AUTH-113', 'No direito internacional publico, o principio da igualdade soberana dos Estados implica:', '["Que todos os Estados tem os mesmos direitos e deveres, independentemente de poder.","Que Estados mais fortes tem mais direitos.","Que apenas Estados-membros da ONU sao soberanos.","Que a soberania pode ser suspensa por decisao unilateral.","Que Estados pequenos nao tem voto."]'::jsonb, 0, 'A igualdade soberana e principio basico do direito internacional, atribuindo iguais direitos e deveres aos Estados.', 'medium', 'Principios do direito internacional publico', 'multiple_choice', 'published', 5182, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-internacional'), 'LAW-AUTH-114', 'No direito internacional privado, o conflito de leis no tempo e no espaco e resolvido por:', '["A lei do foro, sempre e sem excecao.","Normas de direito internacional privado que indicam a lei aplicavel, conforme o caso.","A lei do pais mais poderoso.","A vontade unilateral do juiz.","A lei do pais de origem do produto."]'::jsonb, 1, 'O direito internacional privado fornece regras de conexao para determinar a lei aplicavel aos casos com elemento estrangeiro.', 'medium', 'Conflito de leis', 'multiple_choice', 'published', 5183, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-previdenciario'), 'LAW-AUTH-115', 'A previdencia social, no Brasil, e organizada com base no principio da:', '["Seletividade e distributividade.","Capitalizacao exclusiva.","Previdencia privada obrigatoria.","Ausencia de contribuicao.","Beneficio proporcional ao lucro."]'::jsonb, 0, 'A seguridade social observa os principios da universalidade, uniformidade, equivalencia e seletividade e distributividade, entre outros.', 'medium', 'Principios da seguridade social', 'multiple_choice', 'published', 5184, 'CEBRASPE', 'Area fiscal'),
((select id from public.subjects where slug='direito-previdenciario'), 'LAW-AUTH-116', 'O beneficio de aposentadoria por idade exige, em regra:', '["Apenas idade minima, sem carencia.","Idade minima e carencia, conforme a legislacao previdenciaria.","Tempo de contribuicao, apenas.","Vinculo empregaticio atual.","Autorizacao judicial."]'::jsonb, 1, 'A aposentadoria por idade exige idade minima e cumprimento da carencia prevista na legislacao.', 'medium', 'Beneficios previdenciarios', 'multiple_choice', 'published', 5185, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direitos-difusos-coletivos'), 'LAW-AUTH-117', 'A acao civil publica pode ser proposta para a protecao de:', '["Interesses individuais homogeneos.","Interesses difusos e coletivos, conforme a lei.","Apenas direitos patrimoniais individuais.","Somente questoes criminais.","Direitos de um unico consumidor."]'::jsonb, 1, 'A acao civil publica protege interesses difusos e coletivos, nos termos da Lei n. 7.347/85 e do CDC.', 'medium', 'Tutela coletiva', 'multiple_choice', 'published', 5186, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direitos-difusos-coletivos'), 'LAW-AUTH-118', 'Os interesses difusos sao caracterizados por:', '["Titularidade individual e divisivel.","Indivisibilidade e titularidade de grupo indeterminado.","Existencia de contrato entre as partes.","Vinculo de parentesco.","Propriedade individual de bem."]'::jsonb, 1, 'Os interesses difusos sao indivisiveis e pertencem a grupo indeterminado, como o meio ambiente e o consumidor.', 'medium', 'Interesses difusos', 'multiple_choice', 'published', 5187, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direitos-humanos'), 'LAW-AUTH-119', 'A dignidade da pessoa humana, na Constituicao, e:', '["Um principio programatico sem eficacia.","Um fundamento da Republica e principio norteador do ordenamento.","Apenas um direito individual.","Um dever do cidadao.","Uma norma de direito internacional privado."]'::jsonb, 1, 'A dignidade da pessoa humana e fundamento da Republica e principio que orienta a interpretacao dos direitos fundamentais.', 'easy', 'Direitos fundamentais', 'multiple_choice', 'published', 5188, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direitos-humanos'), 'LAW-AUTH-120', 'O habeas corpus, como remedio constitucional, protege:', '["A liberdade de locomocao contra ilegalidade ou abuso de poder.","O direito de propriedade.","A liberdade de expressao.","O direito ao silencio.","A igualdade material."]'::jsonb, 0, 'O habeas corpus e o remedio constitucional voltado a protecao da liberdade de locomocao.', 'easy', 'Remedios constitucionais', 'multiple_choice', 'published', 5189, 'FCC', 'OAB'),
((select id from public.subjects where slug='estatuto-crianca-adolescente'), 'LAW-AUTH-121', 'O Estatuto da Crianca e do Adolescente adota como doutrina:', '["A situacao irregular.","A protecao integral.","A assistencia social apenas.","A repressao criminal.","A institucionalizacao obrigatoria."]'::jsonb, 1, 'O ECA adota a doutrina da protecao integral, reconhecendo a crianca e o adolescente como sujeitos de direitos.', 'easy', 'Doutrina da protecao integral', 'multiple_choice', 'published', 5190, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='estatuto-crianca-adolescente'), 'LAW-AUTH-122', 'A medida socioeducativa aplicavel ao adolescente que cometeu ato infracional:', '["Deve ter carater exclusivamente punitivo.","Deve observar a proporcionalidade e a finalidade educativa.","E sempre a internacao, em qualquer caso.","Dispensa acompanhamento psicossocial.","E aplicada sem contraditorio."]'::jsonb, 1, 'As medidas socioeducativas devem ser proporcionais e ter finalidade educativa, respeitado o devido processo.', 'medium', 'Medidas socioeducativas', 'multiple_choice', 'published', 5191, 'FGV', 'OAB'),
((select id from public.subjects where slug='etica-legislacao-profissional'), 'LAW-AUTH-123', 'O exercicio da advocacia e atividade privativa de:', '["Qualquer pessoa com curso superior.","Advogado inscrito na OAB, salvo as excecoes legais.","Estagiario, em qualquer caso.","Bacharel em direito, sem inscricao.","Servidor publico, automaticamente."]'::jsonb, 1, 'A advocacia e atividade privativa de advogado regularmente inscrito na OAB, com as excecoes legais.', 'easy', 'Atividade privativa da advocacia', 'multiple_choice', 'published', 5192, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='etica-legislacao-profissional'), 'LAW-AUTH-124', 'O advogado deve guardar sigilo profissional sobre:', '["Apenas documentos escritos.","Tudo o que for confiado pelo cliente no exercicio da profissao, salvo as excecoes legais.","Somente conversas em audiencia.","Apenas informacoes do cliente pessoa fisica.","Nada, pois o sigilo e facultativo."]'::jsonb, 1, 'O sigilo profissional protege as informacoes confiadas pelo cliente, com as excecoes previstas no Estatuto da OAB.', 'medium', 'Sigilo profissional', 'multiple_choice', 'published', 5193, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-125', 'O ato administrativo discricionario, em regra:', '["E vinculado a lei, sem margem de escolha.","Permite a administracao escolher entre alternativas legais, com motivacao.","Pode ser praticado sem motivacao.","E sempre nulo.","Dispensa publicacao."]'::jsonb, 1, 'O ato discricionario admite escolha entre alternativas legais, mas exige motivacao e observancia dos limites legais.', 'medium', 'Atos administrativos', 'multiple_choice', 'published', 5194, 'VUNESP', 'Carreiras policiais')
